import { Component, OnInit } from '@angular/core';
import { ZahteviService, UnifiedZahtevResponse } from '../../services/zahtevi.service';
import {AuthService} from "../../services/auth.service";

interface UnifiedItem {
  id: string | number;
  tip: string;
  status?: string;
  datumPodnosenja?: string;
  dodatniPodaci?: string;
}

@Component({
  selector: 'app-ostalo',
  templateUrl: './ostalo.component.html',
  styleUrls: ['./ostalo.component.css']
})
export class OstaloComponent implements OnInit {
  zahtevi: UnifiedItem[] = [];
  message = '';
  rola: string = '';

  constructor(private zahteviService: ZahteviService,private authService: AuthService) {}

  ngOnInit(): void {
    this.ucitajZahteve();
    this.rola = this.authService.getRoleFromToken();
  }

  ucitajZahteve(): void {
    this.message = 'Učitavam...';
    this.zahteviService.getMojiZahtevi().subscribe({
      next: (data) => {
        this.zahtevi = this.normalize(data);
        this.message = `Učitano ${this.zahtevi.length} zahteva.`;
      },
      error: (err) => {
        this.message = `Greška: ${err.message}`;
      }
    });
  }

  private normalize(data: UnifiedZahtevResponse): UnifiedItem[] {
    const out: UnifiedItem[] = [];

    (data.licne_karte || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Lična karta',
        status: x.status,
        datumPodnosenja: x.datumVazenja || x.datumIzdavanja // koristimo datum isteka
      })
    );

    (data.oruzje || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Oružje',
        status: x.status,
        datumPodnosenja: x.datumDo || x.datumOd // datum do (isteka) za prikaz
      })
    );

    (data.saobracajne_dozvole || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Saobraćajna dozvola',
        status: x.status,
        datumPodnosenja: x.datumVazenja || x.datumIzdavanja
      })
    );

    (data.vozacke_dozvole || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Vozačka dozvola',
        status: x.status,
        datumPodnosenja: x.datumVazenja || x.datumIzdavanja
      })
    );

    return out;
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

}
<div class="container mt-4" *ngIf="!isEmployer">
  <h2 class="mb-3 text-center">📋 Moji zahtevi</h2>


  <div class="table-responsive" *ngIf="zahtevi.length > 0; else nemaZahteva">
    <table class="table table-striped table-hover table-bordered align-middle shadow-sm">
      <thead class="table-primary text-center">
      <tr>
        <th scope="col">#</th>
        <th scope="col">Tip</th>
        <th scope="col">Status</th>
        <th scope="col">Datum</th>
      </tr>
      </thead>
      <tbody>
      <tr *ngFor="let z of zahtevi; let i = index" class="text-center">
        <td>{{ i + 1 }}</td>
        <td><span class="badge bg-secondary">{{ z.tip }}</span></td>
        <td>
            <span [ngClass]="{
              'badge bg-success': z.status === 'ODOBREN',
              'badge bg-danger': z.status === 'ODBIJEN',
              'badge bg-warning text-dark': z.status === 'NA ČEKANJU'
            }">
              {{ z.status }}
            </span>
        </td>
        <td>{{ z.datumPodnosenja | date: 'dd.MM.yyyy' }}</td>
      </tr>
      </tbody>
    </table>
  </div>

  <ng-template #nemaZahteva>
    <p class="text-center text-muted mt-4">Nema pronađenih zahteva.</p>
  </ng-template>
</div>
